import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.BWuWLRhz.js";const k=JSON.parse('{"title":"CLI Search (lff)","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/cli.md","filePath":"user-guide/cli.md","lastUpdated":1787586465000}'),n={name:"user-guide/cli.md"};function l(r,e,o,h,d,p){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="cli-search-lff" tabindex="-1">CLI Search (lff) <a class="header-anchor" href="#cli-search-lff" aria-label="Permalink to &quot;CLI Search (lff)&quot;">​</a></h1><p>Lertaro includes a lightweight and highly efficient command-line companion named <strong><code>lff</code></strong> (Lertaro Fuzzy Finder) — an interactive fuzzy finder built specifically for terminal power users and shell scripts. It communicates via local named pipes with the running Lertaro App to reuse the in-memory index tree without rescanning drives.</p><h2 id="_1-why-choose-lff" tabindex="-1">1. Why Choose lff <a class="header-anchor" href="#_1-why-choose-lff" aria-label="Permalink to &quot;1. Why Choose lff&quot;">​</a></h2><ul><li><strong>Shared Index, Zero I/O Latency</strong>: Unlike <code>fzf</code> or <code>find</code> that crawl disk sectors from scratch on every run, <code>lff</code> queries Lertaro&#39;s multimillion-item memory index tree in sub-milliseconds.</li><li><strong>Identical Search Syntax</strong>: Inherits Lertaro&#39;s fuzzy jump matching, Chinese pinyin aliases, and modifier operators (see <a href="./search-syntax.html"><strong>Search Syntax</strong></a>).</li><li><strong>Fast Fail-Safe</strong>: Automatically detects whether Lertaro App is running. If not, it prints a clear error message to <code>stderr</code> and exits immediately without hanging your terminal.</li></ul><h2 id="_2-installation-path-setup" tabindex="-1">2. Installation &amp; PATH Setup <a class="header-anchor" href="#_2-installation-path-setup" aria-label="Permalink to &quot;2. Installation &amp; PATH Setup&quot;">​</a></h2><p><code>lff.exe</code> ships directly inside the Lertaro package:</p><ul><li><strong>Installer</strong>: Check <strong>Add lff CLI search tool to PATH</strong> in the setup wizard to make <code>lff</code> accessible anywhere in your terminal.</li><li><strong>Portable Edition</strong>: Manually add the unzipped folder path to your user or system <code>PATH</code> environment variable.</li></ul><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>After updating PATH, open a new terminal window for the change to take effect; existing shell sessions will not reflect environment changes automatically.</p></div><h2 id="_3-interactive-ui-keybindings" tabindex="-1">3. Interactive UI &amp; Keybindings <a class="header-anchor" href="#_3-interactive-ui-keybindings" aria-label="Permalink to &quot;3. Interactive UI &amp; Keybindings&quot;">​</a></h2><p>Run <code>lff</code> in any terminal to open the full-screen interactive interface:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lff</span></span></code></pre></div><h3 id="keybindings-cheat-sheet" tabindex="-1">Keybindings Cheat Sheet <a class="header-anchor" href="#keybindings-cheat-sheet" aria-label="Permalink to &quot;Keybindings Cheat Sheet&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Key</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Type Characters</strong></td><td style="text-align:left;">Filters search results in real time with fuzzy jump matching.</td></tr><tr><td style="text-align:left;"><code>↑</code> / <code>↓</code></td><td style="text-align:left;">Moves the highlight up / down.</td></tr><tr><td style="text-align:left;"><code>Page Up</code> / <code>Page Down</code></td><td style="text-align:left;">Scrolls up / down by full page.</td></tr><tr><td style="text-align:left;"><code>←</code> / <code>→</code></td><td style="text-align:left;">Moves the cursor horizontally within the search input bar.</td></tr><tr><td style="text-align:left;"><code>Tab</code></td><td style="text-align:left;">Toggles selection/mark on the highlighted row (marked items display a <code>*</code> badge).</td></tr><tr><td style="text-align:left;"><code>Enter</code></td><td style="text-align:left;">Outputs all marked paths (or the highlighted path if none marked) to <code>stdout</code> and exits.</td></tr><tr><td style="text-align:left;"><code>Esc</code> or <code>Ctrl+C</code></td><td style="text-align:left;">Exits cleanly without outputting anything.</td></tr></tbody></table><h2 id="_4-pre-filling-queries-pipeline-input" tabindex="-1">4. Pre-filling Queries &amp; Pipeline Input <a class="header-anchor" href="#_4-pre-filling-queries-pipeline-input" aria-label="Permalink to &quot;4. Pre-filling Queries &amp; Pipeline Input&quot;">​</a></h2><p>You can provide an initial search term directly via command-line arguments or standard input:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Via argument</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lff</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Via standard input pipeline</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> report</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> lff</span></span></code></pre></div><p>Both open the interactive TUI pre-populated with <code>report</code> as the initial filter, allowing you to refine the search or press <code>Enter</code> directly to confirm.</p><h2 id="_5-multi-selection-batch-output" tabindex="-1">5. Multi-selection &amp; Batch Output <a class="header-anchor" href="#_5-multi-selection-batch-output" aria-label="Permalink to &quot;5. Multi-selection &amp; Batch Output&quot;">​</a></h2><p>Press <code>Tab</code> to mark items. <strong>Marked selections persist even when you change your search query</strong>.</p><p>You can search for <code>doc</code> to mark several Word documents, clear the query, search <code>pdf</code> to mark several reports, and press <code>Enter</code> — <code>lff</code> outputs all marked paths across queries line-by-line to standard output.</p><h2 id="_6-shell-scripting-examples" tabindex="-1">6. Shell Scripting Examples <a class="header-anchor" href="#_6-shell-scripting-examples" aria-label="Permalink to &quot;6. Shell Scripting Examples&quot;">​</a></h2><p><code>lff</code> renders its TUI directly into the console buffer without polluting the standard output stream. Only the final confirmed path strings are written to <code>stdout</code>, making it ideal for piping into other tools:</p><h3 id="powershell-workflows" tabindex="-1">PowerShell Workflows <a class="header-anchor" href="#powershell-workflows" aria-label="Permalink to &quot;PowerShell Workflows&quot;">​</a></h3><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Open the selected file in VS Code</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">code (lff)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Assign chosen directory to a variable and navigate to it</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$target </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> lff; cd $target</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Pipe results as FileInfo objects down the pipeline</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lff </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Get-Item</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Select-Object</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Name</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Length</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> LastWriteTime</span></span></code></pre></div><h3 id="cmd-batch-workflows" tabindex="-1">CMD / Batch Workflows <a class="header-anchor" href="#cmd-batch-workflows" aria-label="Permalink to &quot;CMD / Batch Workflows&quot;">​</a></h3><div class="language-cmd vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:: Process selected paths line</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">by</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">line </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> loop</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /f </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;delims=&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> %</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">i in (</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">&#39;lff&#39;) do code &quot;%i&quot;</span></span></code></pre></div><h2 id="_7-limitations-intentional-choices" tabindex="-1">7. Limitations &amp; Intentional Choices <a class="header-anchor" href="#_7-limitations-intentional-choices" aria-label="Permalink to &quot;7. Limitations &amp; Intentional Choices&quot;">​</a></h2><ul><li><strong>Requires Foreground App</strong>: <code>lff</code> relies on the running Lertaro App instance for querying; it does not perform standalone indexing.</li><li><strong>No GUI Previews</strong>: Optimized exclusively for fast terminal piping. For interactive media/rich text previews, use Lertaro&#39;s GUI <a href="./actions-and-preview.html"><strong>Actions &amp; Preview</strong></a>.</li></ul>`,28)])])}const g=t(n,[["render",l]]);export{k as __pageData,g as default};
